function sumTo(n) {
  if (n === 0) return 0;            // base case
  return n + sumTo(n - 1);          // waits for sumTo(n - 1), then adds n
}

def sum_to(n):
    if n == 0:
        return 0                  # base case
    return n + sum_to(n - 1)      # waits for sum_to(n - 1), then adds n

long sumTo(int n) {
    if (n == 0) return 0;             // base case
    return n + sumTo(n - 1);          // waits for sumTo(n - 1), then adds n
}

long long sumTo(int n) {
    if (n == 0) return 0;             // base case
    return n + sumTo(n - 1);          // waits for sumTo(n - 1), then adds n
}

function sumTo(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) total += i;   // no calls, one frame
  return total;
}

def sum_to(n):
    total = 0
    for i in range(1, n + 1):
        total += i                # no calls, one frame
    return total

long sumTo(int n) {
    long total = 0;
    for (int i = 1; i <= n; i++) total += i;   // no calls, one frame
    return total;
}

long long sumTo(int n) {
    long long total = 0;
    for (int i = 1; i <= n; i++) total += i;   // no calls, one frame
    return total;
}

function sumTo(n, total = 0) {
  if (n === 0) return total;
  return sumTo(n - 1, total + n);   // tail call: nothing left to do after it
}

def sum_to(n, total=0):
    if n == 0:
        return total
    return sum_to(n - 1, total + n)   # tail call: nothing left to do after it

long sumTo(int n) {
    return sumTo(n, 0);
}

long sumTo(int n, long total) {
    if (n == 0) return total;
    return sumTo(n - 1, total + n);   // tail call: nothing left to do after it
}

long long sumTo(int n, long long total = 0) {
    if (n == 0) return total;
    return sumTo(n - 1, total + n);   // tail call: nothing left to do after it
}
